import numpy as np
D=np.load('/app/output/tcp_jacobian.npz'); J=D['jacobian'];
p=D['tcp']; target=np.array([.05,.08,1.25]);
for scale in [1.,.5,.25]:
 d=np.r_[scale*(target-p),np.zeros(3)]; dq=np.linalg.pinv(J)@d
 print(scale,dq, 'norm',np.linalg.norm(dq),'dp pred',J[:3]@dq)
print('singular',np.linalg.svd(J)[1])
