python - <<'PY'
import numpy as np
from scipy.spatial.transform import Rotation
from rcb_client import Robot
r=Robot(); o=r.get_obs(cameras=['left'],video='none'); n=np.array(o.meta['proprio']['now']); cmd=n[23:30].copy();
def measure():
 o=r.get_obs(cameras=['left'],video='none'); return np.array(o.meta['proprio']['now'])
def go(q):
 a=np.tile(np.r_[q,.04,.04],(15,1)); return r.submit('joint_position',a,dt=.1,interpolate='linear',cameras=['left'],video='none')
for j in [0,3]:
 vals=[]
 for s in [1,-1]:
  q=cmd.copy();q[j]+=s*.10; z=go(q);v=np.array(z.meta['proprio']['now']);vals.append(v); go(cmd)
 print('j',j+1,'dqactual',vals[0][j]-vals[1][j], 'q+',vals[0][j],'q-',vals[1][j],'tcp+',vals[0][16:19],'tcp-',vals[1][16:19])
print('status',r.status()); print('now',measure()[16:23])
